import{_ as s,o as t,c as n,aN as e}from"./chunks/framework.D31DlcCL.js";const l="/img/math-shape-patterns.svg",d=JSON.parse('{"title":"奥数思维：图形找规律，发现形状中的“潜规则”","description":"图形不仅是好看的，它们也遵守着严格的排列纪律。本文教你如何从形状、颜色、数量、位置四个维度破解图形规律题，提升你的空间逻辑思维。","frontmatter":{"title":"奥数思维：图形找规律，发现形状中的“潜规则”","date":"2026-02-14T09:00:00.000Z","categories":["数学"],"tags":["小学奥数","图形规律","空间想象","观察训练"],"description":"图形不仅是好看的，它们也遵守着严格的排列纪律。本文教你如何从形状、颜色、数量、位置四个维度破解图形规律题，提升你的空间逻辑思维。","cover":"/img/math-shape-patterns.svg","top_img":"/img/math-shape-patterns.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-olympiad-shape-patterns.md","filePath":"posts/primary-math-olympiad-shape-patterns.md","lastUpdated":null}'),r={name:"posts/primary-math-olympiad-shape-patterns.md"};function o(p,a,m,i,c,h){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="奥数思维-图形找规律-发现形状中的-潜规则" tabindex="-1">奥数思维：图形找规律，发现形状中的“潜规则” <a class="header-anchor" href="#奥数思维-图形找规律-发现形状中的-潜规则" aria-label="Permalink to &quot;奥数思维：图形找规律，发现形状中的“潜规则”&quot;">​</a></h1><p>在奥数考试中，图形规律题就像是“视觉版的脑筋急转弯”。一串奇奇怪怪的图形排排坐，问你下一个是谁。</p><p>很多同学看一眼就晕了。其实，图形的变化逃不出这四个维度：<strong>数量、形状、颜色、位置</strong>。只要你顺着这四条线索去搜寻，真相就会浮出水面。</p><hr><h2 id="一、-四大核心搜寻维度" tabindex="-1">一、 四大核心搜寻维度 <a class="header-anchor" href="#一、-四大核心搜寻维度" aria-label="Permalink to &quot;一、 四大核心搜寻维度&quot;">​</a></h2><p><img src="'+l+'" alt="图形规律搜索示意图"></p><ol><li><strong>数一数（数量变化）</strong>： 图形里的线条、小圆点、角的个数是不是在变多或变少？（如：1个圆 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 3个圆 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 6个圆）</li><li><strong>看一看（形状/颜色变化）</strong>： 是不是圆形变方形？或者是红、黄、蓝循环出现？</li><li><strong>转一转（位置变化）</strong>： 图形是不是在顺时针或逆时针旋转？或者是像照镜子一样翻转了？</li><li><strong>叠一叠（组合变化）</strong>： 是不是前两个图形拼在了一起变成了第三个？</li></ol><hr><h2 id="二、-实战模型解析" tabindex="-1">二、 实战模型解析 <a class="header-anchor" href="#二、-实战模型解析" aria-label="Permalink to &quot;二、 实战模型解析&quot;">​</a></h2><h3 id="模型-1-旋转的指针" tabindex="-1">模型 1：旋转的指针 <a class="header-anchor" href="#模型-1-旋转的指针" aria-label="Permalink to &quot;模型 1：旋转的指针&quot;">​</a></h3><p><strong>【例题 1】</strong>：一个正方形里有个小黑点，它先在左上角，再到右上角，再到右下角，请问下一个位置在哪？ <strong>解析</strong>： 观察发现，小黑点在沿着四个角<strong>顺时针旋转</strong>。 左上 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 右上 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 右下 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> <strong>左下</strong>。 <strong>答案</strong>：小黑点在左下角。</p><h3 id="模型-2-数量递增规律" tabindex="-1">模型 2：数量递增规律 <a class="header-anchor" href="#模型-2-数量递增规律" aria-label="Permalink to &quot;模型 2：数量递增规律&quot;">​</a></h3><p><strong>【例题 2】</strong>：如封面图所示，圆圈排成了三角形阵列。 <strong>解析</strong>：</p><ul><li>第一组：1 个</li><li>第二组：3 个（多了 2 个）</li><li>第三组：6 个（多了 3 个） 规律是：每次增加的个数比上一次多 1。下一个应该增加 4 个，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">6 + 4 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>。 <strong>答案</strong>：10 个。</li></ul><hr><h2 id="三、-进阶技巧-整体观察法" tabindex="-1">三、 进阶技巧：整体观察法 <a class="header-anchor" href="#三、-进阶技巧-整体观察法" aria-label="Permalink to &quot;三、 进阶技巧：整体观察法&quot;">​</a></h2><p>有时候单个图形没规律，要看这一组图形的整体。</p><ul><li>比如：每一行都有一个圆、一个方、一个三角。</li><li>只要看缺了哪一个，就能补上去。</li></ul><hr><h2 id="四、-避坑指南-分清-顺时针-和-逆时针" tabindex="-1">四、 避坑指南：分清“顺时针”和“逆时针” <a class="header-anchor" href="#四、-避坑指南-分清-顺时针-和-逆时针" aria-label="Permalink to &quot;四、 避坑指南：分清“顺时针”和“逆时针”&quot;">​</a></h2><p>旋转方向搞反是图形题最冤枉的扣分点。</p><ul><li><strong>顺时针</strong>：12 点 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 3 点 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 6 点方向。</li><li><strong>逆时针</strong>：12 点 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 9 点 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 6 点方向。</li></ul><hr><h2 id="五、-练一练-视觉侦探挑战" tabindex="-1">五、 练一练（视觉侦探挑战） <a class="header-anchor" href="#五、-练一练-视觉侦探挑战" aria-label="Permalink to &quot;五、 练一练（视觉侦探挑战）&quot;">​</a></h2><ol><li><strong>形状关</strong>：○ □ △ ○ □ ( \\quad )</li><li><strong>位置关</strong>：一个箭头指向上，然后指向右，然后指向下，下一个指向哪？</li><li><strong>组合关</strong>：左半圆 + 右半圆 = 圆；左三角形 + ( \\quad ) = 大三角形？</li></ol><hr><p><em>总结：找图形规律就是“找茬”和“找同”的过程。冷静观察，按维度搜寻，你就是空间逻辑小达人！</em></p>',27)])])}const u=s(r,[["render",o]]);export{d as __pageData,u as default};
